<div class="agent-flow" aria-label="Flujo de coordinación"><?php foreach(['Coordinador'=>'Organiza la revisión','Inventario'=>'Detecta stock de 0 a 5','Análisis'=>'Prioriza con ventas de 30 días','Notificaciones'=>'Registra alertas sin duplicarlas'] as $nombre=>$descripcion): ?><article><span><?= e($nombre) ?></span><p><?= e($descripcion) ?></p></article><?php endforeach; ?></div>
<section class="agents-telegram"><div><h2>Revisión automática · <?= is_array($automatizacion)?'Programada cada '.(int)$automatizacion['intervalo_minutos'].' minutos':'Sin programar' ?></h2><p><?= is_array($automatizacion)?'Programador de tareas de Windows. Requiere equipo encendido, tu sesión iniciada, MySQL e internet. También puedes ejecutar una revisión manual.':'Puedes ejecutar la revisión manual desde este panel.' ?></p><?php if(is_array($ultimaAuto)): ?><p>Última ejecución automática: <?= e((new DateTimeImmutable($ultimaAuto['fecha_utc']))->setTimezone(new DateTimeZone('America/Lima'))->format('d/m/Y H:i:s')) ?> · <?= (int)$ultimaAuto['codigo']===0?'Completada':'Requiere revisión' ?></p><p><?= nl2br(e($ultimaAuto['resultado'])) ?></p><?php endif; ?></div></section>
