<?php if(!$resultado): ?><div class="agents-empty"><h2>Los agentes están listos para su primera revisión.</h2><p>Pulsa «Ejecutar revisión» para analizar el inventario actual y registrar las alertas en este panel.</p></div><?php else: ?>
<div class="dashboard-cards"><article class="card-stat"><h3>Productos con stock bajo</h3><div class="number"><?= (int)$resultado['inventario']['total'] ?></div></article><article class="card-stat"><h3>Agotados</h3><div class="number"><?= (int)$resultado['inventario']['agotados'] ?></div></article><article class="card-stat"><h3>Alertas nuevas o cambiadas</h3><div class="number"><?= (int)$resultado['notificaciones']['nuevas'] ?></div></article><article class="card-stat"><h3>Alertas resueltas</h3><div class="number"><?= (int)$resultado['notificaciones']['resueltas'] ?></div></article></div>
<section class="agents-trace"><h2>Registro de coordinación</h2><p>Última revisión: <?= e($resultado['fecha']) ?> · Ventas del <?= e($resultado['analisis']['periodo']['inicio']) ?> al <?= e($resultado['analisis']['periodo']['fin']) ?></p><?php foreach($resultado['traza'] as $paso): ?><article><strong><?= e(ucfirst($paso['agente'])) ?> → <?= e($paso['destino']) ?></strong><span><?= e($paso['estado']) ?> · <?= e($paso['duracion_ms']) ?> ms</span><p><?= e($paso['objetivo']) ?></p></article><?php endforeach; ?></section>
<section class="agents-trace"><h2>Stock recuperado</h2><p>Se avisa cuando un producto activo con alerta de stock bajo pasa a más de 5 unidades. Desactivarlo o eliminarlo no cuenta como reposición.</p><p><strong><?= (int)($resultado['notificaciones']['nuevas_recuperadas']??0) ?></strong> recuperaciones nuevas en la última revisión.</p><?php $recuperadas=array_reverse($resultado['notificaciones']['recuperadas']??[],true); foreach(array_slice($recuperadas,0,12,true) as $recuperacion): ?><article><strong>✅ <?= e($recuperacion['producto']['nombre']) ?></strong><span><?= e($recuperacion['creada']) ?></span><p>Stock anterior: <?= (int)$recuperacion['stock_anterior'] ?> · Stock actual: <?= (int)$recuperacion['producto']['stock'] ?> unidades · <a href="../productos/editar.php?id=<?= (int)$recuperacion['producto']['id_producto'] ?>">Ver producto</a></p></article><?php endforeach; ?><?php if(!$recuperadas): ?><p>No se han detectado recuperaciones de stock.</p><?php endif; ?><?php if(count($recuperadas)>12): ?><p>Se muestran las 12 recuperaciones más recientes.</p><?php endif; ?></section><h2 class="agents-section-title">Alertas activas</h2><p class="agents-note"><?= e($resultado['analisis']['metodo']) ?></p><table><thead><tr><th>Producto</th><th>Prioridad</th><th>Stock</th><th>Vendidas en 30 días</th><th>Cobertura estimada</th><th>Reposición sugerida</th><th>Ficha</th></tr></thead><tbody><?php foreach($resultado['analisis']['alertas'] as $a): ?><tr><td><strong><?= e($a['nombre']) ?></strong><small class="agent-sku"><?= e($a['codigo']) ?></small></td><td><span class="agent-priority priority-<?= $a['prioridad']==='Crítica'?'critical':($a['prioridad']==='Alta'?'high':'review') ?>"><?= e($a['prioridad']) ?></span></td><td><?= (int)$a['stock'] ?></td><td><?= (int)$a['vendidas_30_dias'] ?></td><td><?= $a['cobertura_dias']===null?'Sin ritmo observable':e($a['cobertura_dias']).' días' ?></td><td><?= (int)$a['reposicion_sugerida'] ?> unidades</td><td><a class="btn-action" href="../productos/editar.php?id=<?= (int)$a['id_producto'] ?>">Revisar</a></td></tr><?php endforeach; ?><?php if(!$resultado['analisis']['alertas']): ?><tr><td colspan="7">No hay productos activos con stock entre 0 y 5 unidades.</td></tr><?php endif; ?></tbody></table>
<?php endif; ?></main></div></body></html>
